"use client";

import { cn } from "@/lib/utils";
import { GpuStage } from "@/registry/ivan/components/gpu-stage/gpu-stage";

import { slimeDefaults } from "./slime-material";
import { SlimeScene } from "./slime-scene";
import type { SlimeSceneProps } from "./slime-scene";

export interface SlimeProps extends SlimeSceneProps {
  className?: string;
  label?: string;
}

const defaultLabel =
  "A glossy green slime that crawls around, drips, reaches for the pointer and splats when clicked";

const fallbackBlob = (ground: string, glow: string) =>
  `radial-gradient(circle at 46% 44%, color-mix(in srgb, ${glow} 55%, ${ground}) 0, ${ground} 24%, transparent 25%)`;

export const Slime = ({
  className,
  label = defaultLabel,
  ink = slimeDefaults.ink,
  paper = slimeDefaults.paper,
  glow = slimeDefaults.glow,
  night = slimeDefaults.night,
  paused = slimeDefaults.paused,
  ...sceneProps
}: SlimeProps) => {
  const ground = night ? ink : paper;
  return (
    <GpuStage
      className={cn(
        "cursor-grab touch-pan-y active:cursor-grabbing",
        className
      )}
      fallback={
        <div
          aria-hidden
          className="absolute inset-0"
          style={{ backgroundImage: fallbackBlob(ground, glow) }}
        />
      }
      ground={ground}
      label={label}
      paused={paused}
    >
      {(isAnimating) => (
        <SlimeScene
          {...sceneProps}
          glow={glow}
          ink={ink}
          night={night}
          paper={paper}
          paused={!isAnimating}
        />
      )}
    </GpuStage>
  );
};

"use client";

import { useFrame, useThree } from "@react-three/fiber";
import { useEffect, useLayoutEffect, useMemo } from "react";
import { PlaneGeometry } from "three";

import {
  createSlimeBody,
  effectiveRadius,
  excitementOf,
  setSlimeBounds,
  settleSlimeBody,
  slimeBalls,
  splatSlimeBody,
  stepSlimeBody,
} from "./slime-body";
import type { PointerInput, SlimeTuning } from "./slime-body";
import {
  applySlimeTones,
  cameraDistance,
  createSlimeMaterial,
  createSlimeUniforms,
  slimeDefaults,
} from "./slime-material";
import type { SlimeTones } from "./slime-material";

export interface SlimeSceneProps {
  ink?: string;
  paper?: string;
  glow?: string;
  night?: boolean;
  viscosity?: number;
  reach?: number;
  veins?: number;
  paused?: boolean;
}

const frameHalfHeight = 1.3;
const warmUpSeconds = 1.4;
const splatSeconds = 0.5;

class SlimeRig {
  readonly uniforms = createSlimeUniforms();
  readonly material = createSlimeMaterial(this.uniforms);
  readonly geometry = new PlaneGeometry(2, 2);
  private readonly body = createSlimeBody();
  private pointer: PointerInput | null = null;
  private halfWidth = frameHalfHeight;
  private halfHeight = frameHalfHeight;
  private tuning: SlimeTuning = {
    reach: slimeDefaults.reach,
    viscosity: slimeDefaults.viscosity,
  };

  private isWarm = false;
  private hasPendingPress = false;

  constructor() {
    this.sync();
  }

  private warmUp() {
    this.isWarm = true;
    settleSlimeBody(this.body, warmUpSeconds, this.tuning);
    splatSlimeBody(this.body, this.tuning);
    settleSlimeBody(this.body, splatSeconds, this.tuning);
    this.sync();
  }

  applyTones(tones: SlimeTones, veins: number) {
    applySlimeTones(this.uniforms, tones);
    this.uniforms.veins.value = veins;
  }

  applyTuning(tuning: SlimeTuning) {
    this.tuning = tuning;
  }

  applyViewport(width: number, height: number, pixelRatio: number) {
    const aspect = width / Math.max(height, 1);
    this.halfHeight =
      aspect < 1.25 ? (frameHalfHeight * 1.25) / aspect : frameHalfHeight;
    this.halfWidth = this.halfHeight * aspect;
    setSlimeBounds(this.body, {
      halfHeight: this.halfHeight,
      halfWidth: this.halfWidth,
    });
    if (!this.isWarm && width > 0 && height > 0) {
      this.warmUp();
    }
    this.uniforms.aspect.value = aspect;
    this.uniforms.focal.value = cameraDistance / this.halfHeight;
    this.uniforms.pixel.value =
      (this.halfHeight * 2) / Math.max(height * pixelRatio, 1);
  }

  track(element: HTMLElement, event: PointerEvent, pressed: boolean) {
    const bounds = element.getBoundingClientRect();
    const x = ((event.clientX - bounds.left) / bounds.width) * 2 - 1;
    const y = 1 - ((event.clientY - bounds.top) / bounds.height) * 2;
    this.pointer = { pressed, x: x * this.halfWidth, y: y * this.halfHeight };
    if (pressed) {
      this.hasPendingPress = true;
    }
  }

  isPressed() {
    return this.pointer?.pressed ?? false;
  }

  forget() {
    this.pointer = null;
  }

  advance(delta: number) {
    const { pointer } = this;
    const input =
      pointer && this.hasPendingPress ? { ...pointer, pressed: true } : pointer;
    this.hasPendingPress = false;
    stepSlimeBody(this.body, delta, input, this.tuning);
    this.sync();
  }

  private sync() {
    const { body, uniforms } = this;
    for (const [index, entry] of slimeBalls(body).entries()) {
      uniforms.ballValues[index]?.set(
        entry.x,
        entry.y,
        entry.z,
        effectiveRadius(entry)
      );
    }
    uniforms.excite.value = excitementOf(body);
    uniforms.touch.value.set(body.touch.x, body.touch.y, body.touch.strength);
    uniforms.time.value = body.time;
  }

  dispose() {
    this.material.dispose();
    this.geometry.dispose();
  }
}

const usePointerTracking = (rig: SlimeRig) => {
  const element = useThree((state) => state.gl.domElement);

  useEffect(() => {
    const onMove = (event: PointerEvent) =>
      rig.track(element, event, rig.isPressed());
    const onDown = (event: PointerEvent) => {
      element.setPointerCapture(event.pointerId);
      rig.track(element, event, true);
    };
    const onUp = (event: PointerEvent) => {
      if (element.hasPointerCapture(event.pointerId)) {
        element.releasePointerCapture(event.pointerId);
      }
      rig.track(element, event, false);
    };
    const onLeave = (event: PointerEvent) => {
      if (event.pointerType === "mouse" && !rig.isPressed()) {
        rig.forget();
      }
    };
    const onCancel = () => rig.forget();
    element.addEventListener("pointermove", onMove);
    element.addEventListener("pointerdown", onDown);
    element.addEventListener("pointerup", onUp);
    element.addEventListener("pointerleave", onLeave);
    element.addEventListener("pointercancel", onCancel);
    return () => {
      element.removeEventListener("pointermove", onMove);
      element.removeEventListener("pointerdown", onDown);
      element.removeEventListener("pointerup", onUp);
      element.removeEventListener("pointerleave", onLeave);
      element.removeEventListener("pointercancel", onCancel);
    };
  }, [element, rig]);
};

export const SlimeScene = ({
  ink = slimeDefaults.ink,
  paper = slimeDefaults.paper,
  glow = slimeDefaults.glow,
  night = slimeDefaults.night,
  viscosity = slimeDefaults.viscosity,
  reach = slimeDefaults.reach,
  veins = slimeDefaults.veins,
  paused = slimeDefaults.paused,
}: SlimeSceneProps) => {
  const width = useThree((state) => state.size.width);
  const height = useThree((state) => state.size.height);
  const pixelRatio = useThree((state) => state.viewport.dpr);
  const invalidate = useThree((state) => state.invalidate);
  const rig = useMemo(() => new SlimeRig(), []);

  usePointerTracking(rig);

  useEffect(() => () => rig.dispose(), [rig]);

  useLayoutEffect(() => {
    rig.applyTones({ glow, ink, night, paper }, veins);
    invalidate();
  }, [glow, ink, invalidate, night, paper, rig, veins]);

  useLayoutEffect(() => {
    rig.applyTuning({ reach, viscosity });
  }, [reach, rig, viscosity]);

  useLayoutEffect(() => {
    rig.applyViewport(width, height, pixelRatio);
    invalidate();
  }, [height, invalidate, pixelRatio, rig, width]);

  useFrame((_, delta) => {
    if (!paused) {
      rig.advance(delta);
    }
  });

  return (
    <mesh
      frustumCulled={false}
      geometry={rig.geometry}
      material={rig.material}
    />
  );
};

import { Color, Vector3, Vector4 } from "three";
import {
  Break,
  Fn,
  If,
  Loop,
  abs,
  clamp,
  cos,
  dot,
  exp,
  float,
  length,
  max,
  min,
  mix,
  mx_noise_float,
  normalize,
  positionGeometry,
  pow,
  reflect,
  refract,
  sin,
  smoothstep,
  sqrt,
  uniform,
  uniformArray,
  uv,
  vec3,
  vec4,
} from "three/tsl";
import { MeshBasicNodeMaterial } from "three/webgpu";
import type { Node } from "three/webgpu";

import { ballCount } from "./slime-body";

export const slimeDefaults = {
  glow: "#7ddc3c",
  ink: "#0b0b0c",
  night: true,
  paper: "#edece8",
  paused: false,
  reach: 1,
  veins: 1,
  viscosity: 1,
} as const;

export const cameraDistance = 3.2;
const blend = 0.3;
const cullMargin = blend * 0.6 + 0.03;
const marchSteps = 72;
const veinSamples = 4;

export const createSlimeUniforms = () => {
  const ballValues = Array.from(
    { length: ballCount },
    () => new Vector4(0, 0, 0, -0.4)
  );
  return {
    aspect: uniform(1),
    ballValues,
    balls: uniformArray<"vec4">(ballValues, "vec4"),
    excite: uniform(0),
    focal: uniform(1.9),
    glow: uniform(new Color(slimeDefaults.glow)),
    ground: uniform(new Color(slimeDefaults.ink)),
    ink: uniform(new Color(slimeDefaults.ink)),
    night: uniform(1),
    paper: uniform(new Color(slimeDefaults.paper)),
    pixel: uniform(0.003),
    time: uniform(0),
    touch: uniform(new Vector3()),
    veins: uniform(1),
  };
};

export type SlimeUniforms = ReturnType<typeof createSlimeUniforms>;

export const createSlimeMaterial = (uniforms: SlimeUniforms) => {
  const field = Fn(([point]: [Node<"vec3">]) => {
    const merged = float(10).toVar();
    Loop(ballCount, ({ i }) => {
      const entry = uniforms.balls.element(i);
      const gap = length(point.sub(entry.xyz)).sub(entry.w);
      const overlap = max(float(blend).sub(abs(merged.sub(gap))), 0).div(blend);
      merged.assign(
        min(merged, gap).sub(overlap.mul(overlap).mul(blend * 0.25))
      );
    });
    const ripple = sin(point.x.mul(9).add(uniforms.time.mul(1.3)))
      .mul(sin(point.y.mul(8).sub(uniforms.time.mul(1.1))))
      .mul(sin(point.z.mul(7).add(uniforms.time.mul(0.9))))
      .mul(0.012);
    return merged.add(ripple);
  }).setLayout({
    inputs: [{ name: "point", type: "vec3" }],
    name: "slimeField",
    type: "float",
  });

  const normalAt = Fn(([point]: [Node<"vec3">]) => {
    const offset = 0.002;
    const a = vec3(1, -1, -1);
    const b = vec3(-1, -1, 1);
    const c = vec3(-1, 1, -1);
    const d = vec3(1, 1, 1);
    return normalize(
      a
        .mul(field(point.add(a.mul(offset))))
        .add(b.mul(field(point.add(b.mul(offset)))))
        .add(c.mul(field(point.add(c.mul(offset)))))
        .add(d.mul(field(point.add(d.mul(offset)))))
    );
  }).setLayout({
    inputs: [{ name: "point", type: "vec3" }],
    name: "slimeNormal",
    type: "vec3",
  });

  const depthAt = Fn(([point, normal]: [Node<"vec3">, Node<"vec3">]) => {
    const near = clamp(field(point.sub(normal.mul(0.08))).div(-0.08), 0, 1);
    const middle = clamp(field(point.sub(normal.mul(0.22))).div(-0.22), 0, 1);
    const far = clamp(field(point.sub(normal.mul(0.45))).div(-0.45), 0, 1);
    return near.mul(0.25).add(middle.mul(0.35)).add(far.mul(0.4));
  }).setLayout({
    inputs: [
      { name: "point", type: "vec3" },
      { name: "normal", type: "vec3" },
    ],
    name: "slimeDepth",
    type: "float",
  });

  const veinsAt = Fn(([point, ray]: [Node<"vec3">, Node<"vec3">]) => {
    const amount = float(0).toVar();
    Loop(veinSamples, ({ i }) => {
      const travel = float(i).add(1).mul(0.075);
      const sample = point.add(ray.mul(travel));
      const drift = vec3(0, 0, uniforms.time.mul(0.12));
      const warp = mx_noise_float(sample.mul(0.9).sub(drift)).mul(0.9);
      const veinPoint = sample.mul(2.2).add(drift).add(warp);
      const noise = mx_noise_float(veinPoint);
      const step = 0.02;
      const slope = length(
        vec3(
          mx_noise_float(veinPoint.add(vec3(step, 0, 0))),
          mx_noise_float(veinPoint.add(vec3(0, step, 0))),
          mx_noise_float(veinPoint.add(vec3(0, 0, step)))
        )
          .sub(noise)
          .div(step)
      );
      const isoDistance = abs(noise).div(max(slope, 0.2));
      const reach = smoothstep(
        -0.25,
        0.3,
        mx_noise_float(
          sample.mul(0.8).add(vec3(7.3, 1.1, uniforms.time.mul(0.05)))
        )
      );
      const line = float(1).sub(smoothstep(0.006, 0.03, isoDistance));
      amount.addAssign(line.mul(reach).mul(exp(travel.mul(-3))));
    });
    return amount.mul(0.55);
  }).setLayout({
    inputs: [
      { name: "point", type: "vec3" },
      { name: "ray", type: "vec3" },
    ],
    name: "slimeVeins",
    type: "float",
  });

  const shade = Fn(() => {
    const ndc = uv().mul(2).sub(1);
    const origin = vec3(0, 0, cameraDistance);
    const ray = normalize(
      vec3(ndc.x.mul(uniforms.aspect), ndc.y, uniforms.focal.negate())
    );
    const ground = uniforms.ground.rgb;
    const result = vec3(ground).toVar();

    const enter = float(1000).toVar();
    const leave = float(0).toVar();
    Loop(ballCount, ({ i }) => {
      const entry = uniforms.balls.element(i);
      If(entry.w.greaterThan(0), () => {
        const offset = origin.sub(entry.xyz);
        const along = dot(offset, ray);
        const radius = entry.w.add(cullMargin);
        const spread = along
          .mul(along)
          .sub(dot(offset, offset))
          .add(radius.mul(radius));
        If(spread.greaterThan(0), () => {
          const root = sqrt(spread);
          enter.assign(min(enter, along.negate().sub(root)));
          leave.assign(max(leave, along.negate().add(root)));
        });
      });
    });

    If(leave.greaterThan(enter), () => {
      const travel = max(enter, 0).toVar();
      const exit = leave;
      const nearest = float(1000).toVar();
      const nearestTravel = float(0).toVar();
      const hit = float(0).toVar();

      Loop(marchSteps, () => {
        const distance = field(origin.add(ray.mul(travel)));
        If(distance.lessThan(nearest), () => {
          nearest.assign(distance);
          nearestTravel.assign(travel);
        });
        If(distance.lessThan(0.0012), () => {
          hit.assign(1);
          Break();
        });
        travel.addAssign(distance.mul(0.9));
        If(travel.greaterThan(exit), () => {
          Break();
        });
      });

      const edge = uniforms.pixel.mul(1.6);
      const coverage = max(hit, float(1).sub(smoothstep(0, edge, nearest)));

      If(coverage.greaterThan(0), () => {
        const point = origin.add(ray.mul(nearestTravel));
        const normal = normalAt(point);
        const view = ray.negate();
        const facing = clamp(dot(normal, view), 0, 1);
        const fresnel = pow(float(1).sub(facing), 3);
        const depth = depthAt(point, normal);
        const { night } = uniforms;

        const keyLight = normalize(vec3(-0.45, 0.75, 0.55));
        const diffuse = clamp(dot(normal, keyLight).mul(0.5).add(0.5), 0, 1);
        const backLight = normalize(vec3(0.3, 0.45, -1));
        const thin = pow(float(1).sub(depth), 2);
        const scatter = pow(
          clamp(dot(view, backLight.add(normal.mul(0.6)).negate()), 0, 1),
          4
        )
          .mul(thin)
          .add(pow(float(1).sub(depth), 3).mul(0.3));

        const reflected = reflect(ray, normal);
        const softbox = smoothstep(0.35, 0.9, reflected.y).mul(
          smoothstep(-0.2, 0.5, reflected.z)
        );
        const window = smoothstep(
          0.93,
          0.985,
          dot(reflected, normalize(vec3(-0.8, 0.35, 0.5)))
        );
        const envMask = clamp(softbox.mul(0.9).add(window), 0, 1);
        const highlight = pow(
          max(dot(normal, normalize(keyLight.add(view))), 0),
          160
        ).mul(1.4);

        const film = depth
          .mul(1.3)
          .add(fresnel.mul(0.9))
          .add(mx_noise_float(point.mul(1.7)).mul(0.35))
          .add(uniforms.time.mul(0.02));
        const spectrum = cos(vec3(0, 0.33, 0.67).add(film).mul(6.2832))
          .mul(0.5)
          .add(0.5);
        const grey = dot(spectrum, vec3(0.299, 0.587, 0.114));
        const sheen = mix(vec3(grey), spectrum, 0.6);

        const { glow, ink, paper } = uniforms;
        const touchGap = length(point.sub(vec3(uniforms.touch.xy, 0)));
        const touchGlow = exp(touchGap.mul(touchGap).mul(-5)).mul(
          uniforms.touch.z
        );
        const refracted = refract(ray, normal, 0.75);
        const veins = clamp(
          veinsAt(point, refracted)
            .mul(
              float(0.7).add(uniforms.excite.mul(1.3)).add(touchGlow.mul(0.7))
            )
            .mul(depth.mul(0.5).add(0.5))
            .mul(uniforms.veins),
          0,
          1
        );

        const nightBody = mix(ink.mul(1.1), glow.mul(0.32), 0.55)
          .add(glow.mul(scatter).mul(1.1))
          .add(glow.mul(veins).mul(1.6));
        const dayCore = mix(paper, glow, 0.9);
        const dayBody = mix(mix(paper, glow, 0.35), dayCore, pow(depth, 0.9))
          .mul(diffuse.mul(0.25).add(0.75))
          .add(paper.mul(scatter).mul(0.12));
        const body = mix(
          mix(dayBody, mix(glow, ink, 0.55), veins),
          nightBody,
          night
        );

        const envLow = mix(mix(ink, paper, 0.35), ink.mul(0.5), night);
        const env = mix(envLow, vec3(1), envMask);
        const reflectance = fresnel.mul(0.9).add(0.05);
        const lit = mix(body, env, reflectance).add(
          mix(vec3(1), sheen, 0.3).mul(highlight)
        );
        const dayFilm = mix(
          vec3(1),
          sheen.mul(1.5),
          fresnel.mul(0.7).mul(float(1).sub(night))
        );
        const surface = lit
          .mul(dayFilm)
          .add(sheen.mul(fresnel).mul(0.55).mul(night));

        result.assign(mix(ground, surface, coverage));
      });
    });

    return vec4(result, 1);
  });

  const material = new MeshBasicNodeMaterial();
  material.vertexNode = vec4(positionGeometry.xy, 0, 1);
  material.colorNode = shade();
  material.toneMapped = false;
  material.depthTest = false;
  material.depthWrite = false;
  return material;
};

export interface SlimeTones {
  glow: string;
  ink: string;
  night: boolean;
  paper: string;
}

export const applySlimeTones = (
  uniforms: SlimeUniforms,
  { glow, ink, night, paper }: SlimeTones
) => {
  uniforms.ink.value.set(ink);
  uniforms.paper.value.set(paper);
  uniforms.glow.value.set(glow);
  uniforms.ground.value.set(night ? ink : paper);
  uniforms.night.value = night ? 1 : 0;
};

export const coreCount = 6;
export const dropCount = 10;
export const strandCount = 5;
export const ballCount = coreCount + dropCount + strandCount + 1;

export interface Ball {
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  radius: number;
  presence: number;
}

export interface PointerInput {
  x: number;
  y: number;
  pressed: boolean;
}

export interface SlimeTuning {
  viscosity: number;
  reach: number;
}

export interface StageBounds {
  halfWidth: number;
  halfHeight: number;
}

type DropPhase = "hidden" | "hang" | "fly" | "stick" | "crawl";
type Wall = "floor" | "ceiling" | "left" | "right";

interface Drop extends Ball {
  phase: DropPhase;
  size: number;
  clock: number;
  hold: number;
  wall: Wall | null;
  offset: number;
  hang: number;
  hangSpeed: number;
  hurried: boolean;
}

interface Grab {
  source: "pointer" | "hover";
  x: number;
  y: number;
}

interface Mass {
  x: number;
  y: number;
  vx: number;
  vy: number;
  sx: number;
  sy: number;
  svx: number;
  svy: number;
  targetX: number;
  targetY: number;
  wanderClock: number;
  wanderSpan: number;
  contact: Set<Wall>;
}

export interface SlimeBody {
  mass: Mass;
  core: Ball[];
  drops: Drop[];
  strand: Ball[];
  tip: Ball;
  anchor: number;
  grab: Grab | null;
  cooldown: number;
  dripClock: number;
  dripSpan: number;
  time: number;
  tension: number;
  flash: number;
  touch: { x: number; y: number; strength: number };
  wasPressed: boolean;
  seed: number;
  bounds: StageBounds;
}

const coreRest = [
  [0, 0.02, 0, 0.34],
  [0.27, 0.05, 0.04, 0.23],
  [-0.26, 0.07, -0.04, 0.24],
  [0.13, -0.19, 0.08, 0.22],
  [-0.15, -0.18, -0.06, 0.21],
  [0.02, 0.23, -0.08, 0.2],
] as const;

const massRadius = 0.48;
const massBottom = 0.36;
const hiddenRadius = -0.4;
const tipRadius = 0.13;
const gravity = 3.4;
const maxStep = 1 / 30;
const subSteps = 2;

const ball = (x: number, y: number, z: number, radius: number): Ball => ({
  presence: 0,
  radius,
  vx: 0,
  vy: 0,
  vz: 0,
  x,
  y,
  z,
});

const drop = (): Drop => ({
  ...ball(0, 0, 0, 0.08),
  clock: 0,
  hang: 0,
  hangSpeed: 0,
  hold: 0,
  hurried: false,
  offset: 0,
  phase: "hidden",
  size: 0.08,
  wall: null,
});

const clamp = (value: number, low: number, high: number) =>
  Math.min(Math.max(value, low), high);

const clamp01 = (value: number) => clamp(value, 0, 1);

const springTo = (
  target: Ball,
  x: number,
  y: number,
  z: number,
  stiffness: number,
  damping: number,
  step: number
) => {
  target.vx += ((x - target.x) * stiffness - target.vx * damping) * step;
  target.vy += ((y - target.y) * stiffness - target.vy * damping) * step;
  target.vz += ((z - target.z) * stiffness - target.vz * damping) * step;
  target.x += target.vx * step;
  target.y += target.vy * step;
  target.z += target.vz * step;
};

const random = (body: SlimeBody) => {
  body.seed = (body.seed * 16_807) % 2_147_483_647;
  return body.seed / 2_147_483_647;
};

const spread = (body: SlimeBody, low: number, high: number) =>
  low + random(body) * (high - low);

const dropsOut = (body: SlimeBody) =>
  body.drops.filter((entry) => entry.phase !== "hidden").length;

const massScale = (body: SlimeBody) => 1 - dropsOut(body) * 0.025;

const nearestCore = (body: SlimeBody, x: number, y: number) => {
  let best = 0;
  let bestGap = Number.POSITIVE_INFINITY;
  for (const [index, entry] of body.core.entries()) {
    const gap = Math.hypot(entry.x - x, entry.y - y) - entry.radius;
    if (gap < bestGap) {
      bestGap = gap;
      best = index;
    }
  }
  return { gap: bestGap, index: best };
};

export const snapLength = (reach: number, source: Grab["source"]) =>
  source === "pointer" ? 1 + reach * 0.9 : 0.75 + reach * 0.65;

export const createSlimeBody = (): SlimeBody => {
  const core = coreRest.map(([x, y, z, radius]) => {
    const entry = ball(x - 0.35, y + 0.15, z, radius);
    entry.presence = 1;
    return entry;
  });
  return {
    anchor: 0,
    bounds: { halfHeight: 1.3, halfWidth: 1.3 },
    cooldown: 0,
    core,
    dripClock: 0,
    dripSpan: 1.6,
    drops: Array.from({ length: dropCount }, drop),
    flash: 0,
    grab: null,
    mass: {
      contact: new Set(),
      svx: 0,
      svy: 0,
      sx: 1,
      sy: 1,
      targetX: 0.6,
      targetY: -0.2,
      vx: 0,
      vy: 0,
      wanderClock: 0,
      wanderSpan: 4,
      x: -0.35,
      y: 0.15,
    },
    seed: 48_271,
    strand: Array.from({ length: strandCount }, () =>
      ball(0, 0, 0, hiddenRadius)
    ),
    tension: 0,
    time: 0,
    tip: ball(0, 0, 0, hiddenRadius),
    touch: { strength: 0, x: 0, y: 0 },
    wasPressed: false,
  };
};

export const setSlimeBounds = (body: SlimeBody, bounds: StageBounds) => {
  body.bounds = bounds;
};

const launchDrop = (
  body: SlimeBody,
  entry: Drop,
  x: number,
  y: number,
  angle: number,
  speed: number
) => {
  entry.phase = "fly";
  entry.clock = 0;
  entry.hurried = false;
  entry.wall = null;
  entry.size = spread(body, 0.06, 0.12);
  entry.radius = entry.size;
  entry.x = x;
  entry.y = y;
  entry.z = spread(body, -0.05, 0.08);
  entry.vx = Math.cos(angle) * speed + body.mass.vx * 0.5;
  entry.vy = Math.sin(angle) * speed + body.mass.vy * 0.5;
  entry.vz = 0;
};

const fling = (
  body: SlimeBody,
  count: number,
  angle: number,
  width: number,
  speed: number
) => {
  const { mass } = body;
  const scale = massScale(body);
  let launched = 0;
  for (const entry of body.drops) {
    if (launched >= count) {
      break;
    }
    if (entry.phase !== "hidden") {
      continue;
    }
    const heading = angle + (random(body) - 0.5) * width;
    const x = mass.x + Math.cos(heading) * massRadius * scale * 0.7;
    const y = mass.y + Math.sin(heading) * massRadius * scale * 0.7;
    launchDrop(body, entry, x, y, heading, speed * spread(body, 0.7, 1.15));
    launched += 1;
  }
};

const splat = (body: SlimeBody, reach: number) => {
  const { mass } = body;
  mass.svy -= 6.2;
  mass.svx += 5;
  mass.vy -= 0.25;
  for (const entry of body.core) {
    const dx = entry.x - mass.x;
    entry.vx += dx * 5;
    entry.vy -= 0.6;
  }
  for (const entry of body.drops) {
    if (entry.phase === "crawl" || entry.phase === "stick") {
      entry.hurried = true;
    }
  }
  fling(body, 6, Math.PI / 2, Math.PI * 1.3, 2.4 + reach * 0.8);
  body.flash = 1;
};

export const splatSlimeBody = (body: SlimeBody, tuning: SlimeTuning) =>
  splat(body, tuning.reach);

const lunge = (body: SlimeBody, x: number, y: number, viscosity: number) => {
  const { mass } = body;
  const dx = x - mass.x;
  const dy = y - mass.y;
  const distance = Math.hypot(dx, dy) || 1;
  const kick = 1.7 / Math.sqrt(viscosity);
  mass.vx += (dx / distance) * kick;
  mass.vy += (dy / distance) * kick;
  mass.targetX = x;
  mass.targetY = y;
  mass.wanderClock = 0;
  mass.wanderSpan = 3;
  body.flash = Math.max(body.flash, 0.4);
};

const pickWander = (body: SlimeBody, viscosity: number) => {
  const { bounds, mass } = body;
  mass.targetX = (random(body) * 2 - 1) * bounds.halfWidth * 1.25;
  mass.targetY = (random(body) * 2 - 1) * bounds.halfHeight * 1.25;
  mass.wanderClock = 0;
  mass.wanderSpan = spread(body, 2.6, 5.4) * Math.sqrt(viscosity);
  const dx = mass.targetX - mass.x;
  const dy = mass.targetY - mass.y;
  const distance = Math.hypot(dx, dy) || 1;
  const kick = spread(body, 0.4, 1.1) / Math.sqrt(viscosity);
  mass.vx += (dx / distance) * kick;
  mass.vy += (dy / distance) * kick;
};

const release = (body: SlimeBody, snapped: boolean) => {
  const { grab, tip } = body;
  body.grab = null;
  body.flash = Math.max(body.flash, snapped ? 0.9 : 0.4);
  body.cooldown = snapped ? 1.1 : 0.5;
  const anchor = body.core[body.anchor];
  if (!anchor) {
    return;
  }
  const dx = tip.x - anchor.x;
  const dy = tip.y - anchor.y;
  const length = Math.hypot(dx, dy) || 1;
  anchor.vx += (dx / length) * (snapped ? 1.4 : 0.7);
  anchor.vy += (dy / length) * (snapped ? 1.4 : 0.7);
  if (!(snapped && grab)) {
    return;
  }
  const loose = body.drops.find((entry) => entry.phase === "hidden");
  if (loose) {
    launchDrop(body, loose, tip.x, tip.y, Math.atan2(tip.vy, tip.vx), 0);
    loose.vx = tip.vx * 0.4;
    loose.vy = tip.vy * 0.4;
    loose.size = tipRadius * 0.85;
    loose.presence = 1;
  }
  tip.presence = 0;
};

const startGrab = (
  body: SlimeBody,
  anchor: number,
  source: Grab["source"],
  x: number,
  y: number
) => {
  const anchorBall = body.core[anchor];
  if (!anchorBall) {
    return;
  }
  body.anchor = anchor;
  body.grab = { source, x, y };
  if (body.tip.presence < 0.05) {
    for (const entry of [...body.strand, body.tip]) {
      entry.x = anchorBall.x;
      entry.y = anchorBall.y;
      entry.z = anchorBall.z;
      entry.vx = 0;
      entry.vy = 0;
      entry.vz = 0;
    }
  }
};

const pressDown = (
  body: SlimeBody,
  pointer: PointerInput,
  tuning: SlimeTuning
) => {
  const { mass } = body;
  const gap =
    Math.hypot(pointer.x - mass.x, pointer.y - mass.y) -
    massRadius * massScale(body);
  if (gap > 0.3) {
    lunge(body, pointer.x, pointer.y, tuning.viscosity);
    return;
  }
  splat(body, tuning.reach);
  const nearest = nearestCore(body, pointer.x, pointer.y);
  if (body.grab) {
    body.grab.source = "pointer";
    return;
  }
  startGrab(body, nearest.index, "pointer", pointer.x, pointer.y);
};

const readPointer = (
  body: SlimeBody,
  pointer: PointerInput | null,
  tuning: SlimeTuning
) => {
  const pressed = pointer?.pressed ?? false;
  const justPressed = pressed && !body.wasPressed;
  body.wasPressed = pressed;
  if (!pointer) {
    if (body.grab) {
      release(body, false);
    }
    return;
  }
  if (justPressed) {
    pressDown(body, pointer, tuning);
  }
  if (body.grab?.source === "pointer" && !pressed) {
    release(body, false);
  }
  if (body.grab) {
    body.grab.x = pointer.x;
    body.grab.y = pointer.y;
    if (body.grab.source === "hover") {
      body.anchor = nearestCore(body, body.tip.x, body.tip.y).index;
    }
    return;
  }
  if (pressed || body.cooldown > 0) {
    return;
  }
  const nearest = nearestCore(body, pointer.x, pointer.y);
  if (nearest.gap < 0.1 + tuning.reach * 0.2) {
    startGrab(body, nearest.index, "hover", pointer.x, pointer.y);
  }
};

const wallGap = (body: SlimeBody, wall: Wall, x: number, y: number) => {
  const { halfHeight, halfWidth } = body.bounds;
  if (wall === "left") {
    return -halfWidth - x;
  }
  if (wall === "right") {
    return x - halfWidth;
  }
  if (wall === "floor") {
    return -halfHeight - y;
  }
  return y - halfHeight;
};

const walls: readonly Wall[] = ["left", "right", "floor", "ceiling"];

const wallNormal = (wall: Wall) => {
  if (wall === "left") {
    return { x: -1, y: 0 };
  }
  if (wall === "right") {
    return { x: 1, y: 0 };
  }
  if (wall === "floor") {
    return { x: 0, y: -1 };
  }
  return { x: 0, y: 1 };
};

const hitWall = (body: SlimeBody, wall: Wall, speed: number) => {
  const { mass } = body;
  const across = wall === "left" || wall === "right";
  const squash = Math.min(speed, 2.4) * 2.4;
  if (across) {
    mass.svx -= squash;
    mass.svy += squash * 0.7;
  } else {
    mass.svy -= squash;
    mass.svx += squash * 0.7;
  }
  body.flash = Math.max(body.flash, Math.min(speed, 1) * 0.6);
  if (speed > 0.75) {
    const normal = wallNormal(wall);
    const away = Math.atan2(-normal.y, -normal.x);
    fling(body, 2, away, Math.PI * 0.9, 1.2 + speed * 0.6);
  }
};

const pressMassOnWalls = (body: SlimeBody, step: number, scale: number) => {
  const { mass } = body;
  const reachOut = massRadius * scale;
  let pressX = 0;
  let pressY = 0;
  for (const wall of walls) {
    const normal = wallNormal(wall);
    const depth = wallGap(
      body,
      wall,
      mass.x + normal.x * reachOut,
      mass.y + normal.y * reachOut
    );
    if (depth <= 0) {
      mass.contact.delete(wall);
      continue;
    }
    const speed = mass.vx * normal.x + mass.vy * normal.y;
    if (!mass.contact.has(wall)) {
      mass.contact.add(wall);
      hitWall(body, wall, Math.max(speed, 0));
    }
    mass.vx -= normal.x * depth * 26 * step;
    mass.vy -= normal.y * depth * 26 * step;
    if (speed > 0) {
      mass.vx -= normal.x * speed * 4 * step;
      mass.vy -= normal.y * speed * 4 * step;
    }
    const squeeze = depth / reachOut;
    pressX += normal.x === 0 ? squeeze * 0.6 : -squeeze;
    pressY += normal.y === 0 ? squeeze * 0.6 : -squeeze;
  }
  const { halfHeight, halfWidth } = body.bounds;
  const limitX = Math.max(halfWidth - reachOut * 0.3, 0);
  const limitY = Math.max(halfHeight - reachOut * 0.3, 0);
  mass.x = clamp(mass.x, -limitX, limitX);
  mass.y = clamp(mass.y, -limitY, limitY);
  return { pressX, pressY };
};

const moveMass = (
  body: SlimeBody,
  pointer: PointerInput | null,
  step: number,
  { viscosity }: SlimeTuning
) => {
  const { mass } = body;
  const scale = massScale(body);
  mass.wanderClock += step;
  const toTarget = Math.hypot(mass.targetX - mass.x, mass.targetY - mass.y);
  if (mass.wanderClock > mass.wanderSpan || toTarget < 0.15) {
    pickWander(body, viscosity);
  }
  const crawl = 0.9 / viscosity;
  let ax = ((mass.targetX - mass.x) / (toTarget || 1)) * crawl;
  let ay = ((mass.targetY - mass.y) / (toTarget || 1)) * crawl;
  if (pointer && !pointer.pressed) {
    const dx = pointer.x - mass.x;
    const dy = pointer.y - mass.y;
    const distance = Math.hypot(dx, dy) || 1;
    const lure = clamp01((distance - massRadius * scale * 0.8) / 0.5);
    ax = ax * 0.3 + (dx / distance) * lure * 1.5 * crawl;
    ay = ay * 0.3 + (dy / distance) * lure * 1.5 * crawl;
  }
  if (body.grab?.source === "pointer") {
    const dx = body.tip.x - mass.x;
    const dy = body.tip.y - mass.y;
    ax += dx * body.tension * 3.2;
    ay += dy * body.tension * 3.2;
  }
  mass.vx += ax * step;
  mass.vy += ay * step;
  const drag = Math.exp(-step * (1.2 + viscosity * 0.7));
  mass.vx *= drag;
  mass.vy *= drag;
  mass.x += mass.vx * step;
  mass.y += mass.vy * step;
  const { pressX, pressY } = pressMassOnWalls(body, step, scale);
  const stretchX = Math.abs(mass.vx) * 0.22 - Math.abs(mass.vy) * 0.1;
  const stretchY = Math.abs(mass.vy) * 0.22 - Math.abs(mass.vx) * 0.1;
  const targetX = clamp(1 + stretchX + pressX, 0.55, 1.6);
  const targetY = clamp(1 + stretchY + pressY, 0.55, 1.6);
  const stiffness = 46 / viscosity;
  const damping = 2.6 + viscosity * 1.4;
  mass.svx += ((targetX - mass.sx) * stiffness - mass.svx * damping) * step;
  mass.svy += ((targetY - mass.sy) * stiffness - mass.svy * damping) * step;
  mass.sx = clamp(mass.sx + mass.svx * step, 0.45, 1.8);
  mass.sy = clamp(mass.sy + mass.svy * step, 0.45, 1.8);
};

const moveCore = (
  body: SlimeBody,
  pointer: PointerInput | null,
  step: number,
  { reach, viscosity }: SlimeTuning
) => {
  const { bounds, mass, time } = body;
  const scale = massScale(body);
  const stiffness = 30 / viscosity;
  const damping = 3 + viscosity * 1.5;
  const tip = body.grab ? body.tip : null;
  for (const [index, entry] of body.core.entries()) {
    const rest = coreRest[index];
    if (!rest) {
      continue;
    }
    const sag = rest[1] < 0 ? 0.035 * viscosity : 0;
    let tx =
      mass.x +
      rest[0] * scale * mass.sx +
      Math.sin(time * 0.71 + index * 1.9) * 0.03;
    let ty =
      mass.y +
      (rest[1] * scale - sag) * mass.sy +
      Math.cos(time * 0.53 + index * 2.7) * 0.03;
    const tz = rest[2] + Math.sin(time * 0.61 + index) * 0.05;
    entry.radius =
      rest[3] * scale * (1 + Math.sin(time * 0.9 + index * 1.3) * 0.04);
    if (tip) {
      const pull = index === body.anchor ? 0.2 : 0.05;
      tx += (tip.x - tx) * pull * body.tension;
      ty += (tip.y - ty) * pull * body.tension;
    }
    if (pointer && !pointer.pressed) {
      const dx = pointer.x - tx;
      const dy = pointer.y - ty;
      const distance = Math.hypot(dx, dy);
      const lure =
        clamp01(1 - (distance - entry.radius) / (0.25 + reach * 0.35)) ** 2;
      tx += dx * lure * 0.3;
      ty += dy * lure * 0.3;
    }
    springTo(entry, tx, ty, tz, stiffness, damping, step);
    const limitX = bounds.halfWidth - entry.radius * 0.4;
    const limitY = bounds.halfHeight - entry.radius * 0.4;
    if (Math.abs(entry.x) > limitX) {
      entry.x = Math.sign(entry.x) * limitX;
      entry.vx = 0;
    }
    if (Math.abs(entry.y) > limitY) {
      entry.y = Math.sign(entry.y) * limitY;
      entry.vy = 0;
    }
  }
};

const startDrip = (body: SlimeBody, viscosity: number) => {
  const { bounds, mass } = body;
  body.dripClock = 0;
  body.dripSpan = spread(body, 1.3, 3) * viscosity;
  const hanging = body.drops.filter((entry) => entry.phase === "hang").length;
  const room = mass.y - massBottom - 0.5 > -bounds.halfHeight;
  const entry = body.drops.find((item) => item.phase === "hidden");
  if (!entry || hanging >= 2 || !room || body.grab?.source === "pointer") {
    return;
  }
  entry.phase = "hang";
  entry.clock = 0;
  entry.hang = 0;
  entry.hangSpeed = 0.02;
  entry.offset = spread(body, -0.6, 0.6);
  entry.size = spread(body, 0.08, 0.12);
  entry.hurried = false;
  entry.wall = null;
  entry.x = mass.x;
  entry.y = mass.y;
  entry.z = 0;
};

const hangDrop = (
  body: SlimeBody,
  entry: Drop,
  step: number,
  viscosity: number
) => {
  const { mass } = body;
  const scale = massScale(body);
  entry.hangSpeed += (gravity * 0.1 * step) / viscosity;
  entry.hang += entry.hangSpeed * step;
  entry.radius = entry.size * (0.55 + 0.45 * clamp01(entry.clock / 1.4));
  entry.x = mass.x + entry.offset * massRadius * scale * mass.sx * 0.6;
  entry.y = mass.y - massBottom * scale * mass.sy - entry.hang;
  entry.vx = mass.vx;
  entry.vy = mass.vy - entry.hangSpeed;
  entry.z += (0 - entry.z) * step * 4;
  if (entry.hang > 0.26 + entry.size) {
    entry.phase = "fly";
    entry.clock = 0;
    entry.vy = Math.min(entry.vy, -entry.hangSpeed * 1.5);
  }
};

const stick = (body: SlimeBody, entry: Drop, wall: Wall, viscosity: number) => {
  const { halfHeight, halfWidth } = body.bounds;
  entry.phase = "stick";
  entry.wall = wall;
  entry.clock = 0;
  entry.hold = spread(body, 0.7, 1.6) * viscosity;
  entry.vx = 0;
  entry.vy = 0;
  const inset = entry.size * 0.45;
  if (wall === "left") {
    entry.x = -halfWidth + inset;
  } else if (wall === "right") {
    entry.x = halfWidth - inset;
  } else if (wall === "floor") {
    entry.y = -halfHeight + inset;
  } else {
    entry.y = halfHeight - inset;
  }
};

const flyDrop = (
  body: SlimeBody,
  entry: Drop,
  step: number,
  viscosity: number
) => {
  const { mass } = body;
  entry.vy -= gravity * step;
  const drag = Math.exp(-step * 0.5);
  entry.vx *= drag;
  entry.vy *= drag;
  entry.x += entry.vx * step;
  entry.y += entry.vy * step;
  entry.z += (0 - entry.z) * step * 2;
  const stretch = Math.hypot(entry.vx, entry.vy) * 0.04;
  entry.radius = entry.size * (1 - Math.min(stretch, 0.2));
  for (const wall of walls) {
    if (wallGap(body, wall, entry.x, entry.y) > -entry.size * 0.45) {
      stick(body, entry, wall, viscosity);
      return;
    }
  }
  const home = Math.hypot(entry.x - mass.x, entry.y - mass.y);
  if (entry.clock > 0.3 && home < massRadius * massScale(body) * 0.9) {
    entry.phase = "crawl";
    entry.clock = 0;
  }
};

const stickDrop = (
  body: SlimeBody,
  entry: Drop,
  step: number,
  viscosity: number
) => {
  entry.radius += (entry.size * 1.3 - entry.radius) * (1 - Math.exp(-step * 9));
  if (entry.wall === "left" || entry.wall === "right") {
    entry.y = Math.max(
      entry.y - (0.08 / viscosity) * step,
      -body.bounds.halfHeight + entry.size * 0.45
    );
  }
  const hold = entry.hurried ? entry.hold * 0.4 : entry.hold;
  if (entry.clock < hold) {
    return;
  }
  entry.clock = 0;
  if (entry.wall === "ceiling") {
    entry.phase = "fly";
    entry.vy = -0.1;
    entry.y -= entry.size * 0.3;
    return;
  }
  entry.phase = "crawl";
};

const crawlDrop = (
  body: SlimeBody,
  entry: Drop,
  step: number,
  viscosity: number
) => {
  const { mass } = body;
  const dx = mass.x - entry.x;
  const dy = mass.y - entry.y;
  const distance = Math.hypot(dx, dy) || 1;
  const speed =
    ((entry.hurried ? 1.3 : 0.55) + entry.clock * 0.08) / Math.sqrt(viscosity);
  const wobble = Math.sin(body.time * 3 + entry.size * 90) * 0.25;
  const vx = ((dx - dy * wobble) / distance) * speed;
  const vy = ((dy + dx * wobble) / distance) * speed;
  const ease = 1 - Math.exp(-step * 3);
  entry.vx += (vx - entry.vx) * ease;
  entry.vy += (vy - entry.vy) * ease;
  entry.x += entry.vx * step;
  entry.y += entry.vy * step;
  entry.radius =
    entry.size * (1.05 + Math.sin(body.time * 5 + entry.size * 40) * 0.12);
  if (distance < massRadius * massScale(body) * 0.85) {
    entry.presence = Math.max(0, entry.presence - step * 2.5);
    if (entry.presence <= 0) {
      entry.phase = "hidden";
    }
  }
};

const moveDrops = (body: SlimeBody, step: number, viscosity: number) => {
  body.dripClock += step;
  if (body.dripClock > body.dripSpan) {
    startDrip(body, viscosity);
  }
  const { mass } = body;
  for (const entry of body.drops) {
    entry.clock += step;
    if (entry.phase === "hidden") {
      entry.presence = 0;
      entry.x = mass.x;
      entry.y = mass.y;
      continue;
    }
    if (entry.phase !== "crawl") {
      entry.presence = Math.min(1, entry.presence + step * 10);
    }
    if (entry.phase === "hang") {
      hangDrop(body, entry, step, viscosity);
    } else if (entry.phase === "fly") {
      flyDrop(body, entry, step, viscosity);
    } else if (entry.phase === "stick") {
      stickDrop(body, entry, step, viscosity);
    } else {
      crawlDrop(body, entry, step, viscosity);
    }
  }
};

const moveStrand = (
  body: SlimeBody,
  step: number,
  { reach, viscosity }: SlimeTuning
) => {
  const anchor = body.core[body.anchor];
  if (!anchor) {
    return;
  }
  const { grab, tip } = body;
  if (grab?.source === "pointer") {
    springTo(tip, grab.x, grab.y, 0.05, 240, 22, step);
  } else if (grab) {
    springTo(tip, grab.x, grab.y, 0.05, 90 / viscosity, 9, step);
  } else {
    springTo(tip, anchor.x, anchor.y, anchor.z, 60 / viscosity, 6, step);
  }
  if (grab) {
    tip.presence = Math.min(1, tip.presence + step * 8);
  }
  const dx = tip.x - anchor.x;
  const dy = tip.y - anchor.y;
  const dz = tip.z - anchor.z;
  const length = Math.hypot(dx, dy, dz);
  const limit = snapLength(reach, grab?.source ?? "hover");
  body.tension = clamp01((length - anchor.radius) / (limit - anchor.radius));
  const thinning = Math.min(1, (0.6 / Math.max(length, 0.6)) ** 0.7);
  for (const [index, entry] of body.strand.entries()) {
    const along = (index + 1) / (strandCount + 1);
    const bow = Math.sin(Math.PI * along);
    const sag = bow * length * 0.14 * Math.sqrt(viscosity);
    const lag = 1 + viscosity * 0.45 + index * 0.04;
    if (grab) {
      springTo(
        entry,
        anchor.x + dx * along,
        anchor.y + dy * along - sag,
        anchor.z + dz * along,
        130 / lag,
        12,
        step
      );
      entry.presence = Math.min(1, entry.presence + step * 9);
    } else {
      springTo(entry, anchor.x, anchor.y, anchor.z, 50 + index * 5, 6, step);
    }
    entry.radius = (0.12 - bow ** 0.6 * 0.075) * thinning;
  }
  tip.radius = tipRadius * (1 - body.tension * 0.3);
  if (grab && length > limit) {
    release(body, true);
  }
  if (!body.grab) {
    const settle = length < anchor.radius * 0.9 ? step * 2.4 : 0;
    tip.presence = Math.max(0, tip.presence - settle);
    for (const entry of body.strand) {
      entry.presence = Math.max(0, entry.presence - settle);
    }
  }
};

const moveTouch = (
  body: SlimeBody,
  pointer: PointerInput | null,
  step: number
) => {
  const target = pointer ? 1 : 0;
  body.touch.strength +=
    (target - body.touch.strength) * (1 - Math.exp(-step * 5));
  if (pointer) {
    body.touch.x = pointer.x;
    body.touch.y = pointer.y;
  }
  body.flash *= Math.exp(-step * 2.2);
  body.cooldown = Math.max(0, body.cooldown - step);
};

export const stepSlimeBody = (
  body: SlimeBody,
  delta: number,
  pointer: PointerInput | null,
  tuning: SlimeTuning
) => {
  const step = Math.min(delta, maxStep) / subSteps;
  readPointer(body, pointer, tuning);
  for (let index = 0; index < subSteps; index += 1) {
    body.time += step;
    moveMass(body, pointer, step, tuning);
    moveCore(body, pointer, step, tuning);
    moveDrops(body, step, tuning.viscosity);
    moveStrand(body, step, tuning);
    moveTouch(body, pointer, step);
  }
};

export const settleSlimeBody = (
  body: SlimeBody,
  seconds: number,
  tuning: SlimeTuning
) => {
  const frames = Math.round(seconds * 60);
  for (let index = 0; index < frames; index += 1) {
    stepSlimeBody(body, 1 / 60, null, tuning);
  }
};

export const effectiveRadius = (entry: Ball) =>
  hiddenRadius + (entry.radius - hiddenRadius) * entry.presence;

export const slimeBalls = (body: SlimeBody): readonly Ball[] => [
  ...body.core,
  ...body.drops,
  ...body.strand,
  body.tip,
];

export const excitementOf = (body: SlimeBody) =>
  Math.max(body.tension * 0.85, body.flash, body.touch.strength * 0.35);

"use client";

import { Canvas } from "@react-three/fiber";
import type { GLProps } from "@react-three/fiber";
import { useRef } from "react";
import type { ReactNode } from "react";
import { WebGPURenderer } from "three/webgpu";

import { cn } from "@/lib/utils";
import { useInView } from "@/registry/ivan/hooks/use-in-view";
import { usePrefersReducedMotion } from "@/registry/ivan/hooks/use-prefers-reduced-motion";
import { useWebGLSupport } from "@/registry/ivan/hooks/use-webgl-support";

export interface GpuStageProps {
  ground: string;
  label: string;
  paused: boolean;
  fallback: ReactNode;
  className?: string;
  children: (isAnimating: boolean) => ReactNode;
}

const createRenderer: GLProps = async ({ canvas }) => {
  if (!(canvas instanceof HTMLCanvasElement)) {
    throw new TypeError("GpuStage renders into an HTMLCanvasElement.");
  }
  const renderer = new WebGPURenderer({
    alpha: true,
    antialias: false,
    canvas,
    powerPreference: "high-performance",
  });
  await renderer.init();
  return renderer;
};

export const GpuStage = ({
  ground,
  label,
  paused,
  fallback,
  className,
  children,
}: GpuStageProps) => {
  const frame = useRef<HTMLElement>(null);
  const hasWebGL = useWebGLSupport();
  const isInView = useInView(frame);
  const prefersReducedMotion = usePrefersReducedMotion();
  const isAnimating = isInView && !prefersReducedMotion && !paused;

  return (
    <figure
      aria-label={label}
      className={cn(
        "relative m-0 aspect-4/3 w-full overflow-hidden",
        className
      )}
      ref={frame}
      style={{ backgroundColor: ground }}
    >
      {hasWebGL ? null : fallback}
      {hasWebGL && isInView ? (
        <Canvas
          aria-hidden
          dpr={[1, 1.5]}
          flat
          frameloop={isAnimating ? "always" : "demand"}
          gl={createRenderer}
        >
          {children(isAnimating)}
        </Canvas>
      ) : null}
    </figure>
  );
};

"use client";

import { useSyncExternalStore } from "react";

const reducedMotionQuery = "(prefers-reduced-motion: reduce)";

const subscribe = (onChange: () => void) => {
  const mediaQuery = window.matchMedia(reducedMotionQuery);
  mediaQuery.addEventListener("change", onChange);
  return () => mediaQuery.removeEventListener("change", onChange);
};

const getSnapshot = () => window.matchMedia(reducedMotionQuery).matches;

const getServerSnapshot = () => false;

export const usePrefersReducedMotion = () =>
  useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);

"use client";

import { useSyncExternalStore } from "react";

let cachedSupport: boolean | null = null;

const detectWebGL = () => {
  if (cachedSupport !== null) {
    return cachedSupport;
  }
  try {
    const probe = document.createElement("canvas");
    const context = probe.getContext("webgl2") ?? probe.getContext("webgl");
    context?.getExtension("WEBGL_lose_context")?.loseContext();
    cachedSupport = context !== null;
  } catch {
    cachedSupport = false;
  }
  return cachedSupport;
};

const subscribe = (onChange: () => void) => {
  window.addEventListener("pageshow", onChange);
  return () => window.removeEventListener("pageshow", onChange);
};

const getServerSnapshot = () => true;

export const useWebGLSupport = () =>
  useSyncExternalStore(subscribe, detectWebGL, getServerSnapshot);

"use client";

import { useEffect, useState } from "react";
import type { RefObject } from "react";

export const useInView = (
  target: RefObject<Element | null>,
  rootMargin = "10% 0px"
) => {
  const [isInView, setIsInView] = useState(false);

  useEffect(() => {
    const element = target.current;
    if (!element) {
      return;
    }
    const observer = new IntersectionObserver(
      ([entry]) => setIsInView(entry?.isIntersecting ?? false),
      { rootMargin }
    );
    observer.observe(element);
    return () => observer.disconnect();
  }, [rootMargin, target]);

  return isInView;
};
